package com.quincaisoft.documents.application;
import com.quincaisoft.documents.api.*;import com.quincaisoft.documents.api.DocumentWorkspace.*;
import com.quincaisoft.documents.infrastructure.*;import com.quincaisoft.shared.*;
import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;
import tools.jackson.databind.json.JsonMapper;import java.time.*;import java.util.*;import java.util.function.Supplier;

@Service
public class DocumentWorkspaceService implements DocumentWorkspace {
 private final EntityManager em;private final ScopedTransactions tx;private final JsonMapper json;private final DocumentService originals;private final DocumentSourceReader sources;
 public DocumentWorkspaceService(EntityManager em,ScopedTransactions tx,JsonMapper json,DocumentService originals,DocumentSourceReader sources){this.em=em;this.tx=tx;this.json=json;this.originals=originals;this.sources=sources;}
 public List<Template> templates(){return sources.templates();}
 public List<SourceCandidate> sources(String id){return tx.execute(()->sources.sources(id));}
 private void permission(String p){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||a.getAuthorities().stream().noneMatch(x->x.getAuthority().equals(p)||x.getAuthority().equals("SCOPE_"+p)))throw new AccessDeniedException("Required permission: "+p);}
 public Capture capture(CaptureRequest r){permission("documents:write");if(r==null||r.operationId()==null||r.sourceId()==null)throw new IllegalArgumentException("Operation and source required");sources.authorize(r.templateId());return command(r.operationId(),"DOCUMENT_CAPTURE",r,Capture.class,()->{
  var material=sources.read(r.templateId(),r.sourceId());var issuer=material.originalIssuer()==null?originals.settings():material.originalIssuer();if(issuer.issuerName().isBlank())throw new IllegalStateException("Configure document issuer before capture");var s=TenantContext.current();var row=new CapturedDocument();row.tenantId=s.tenantId();row.companyId=s.companyId();row.branchId=s.branchId();row.id=UUID.randomUUID();row.operationId=r.operationId();row.actorId=s.actorId();row.templateId=r.templateId();row.sourceId=r.sourceId();row.capturedAt=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);var content=new Content("CAPTURE-ENFR-1",sources.template(r.templateId()),issuer,material.body(),s.actorId(),row.capturedAt);row.content=json.writeValueAsString(content);row.sha256=DefaultDocumentService.sha(row.content);em.persist(row);em.flush();event(r.operationId(),"DocumentCaptured",row.id);return view(row);
 });}
 private Capture view(CapturedDocument r){return new Capture(r.id,r.templateId,r.sourceId,r.actorId,r.capturedAt,r.sha256,json.readValue(r.content,Content.class));}
 public Capture get(UUID id){permission("documents:read");return tx.execute(()->{var s=TenantContext.current();var row=em.find(CapturedDocument.class,new DocumentSnapshot.Key(s.tenantId(),s.companyId(),id));if(row==null)throw new NoSuchElementException("Capture not found");sources.authorize(row.templateId);return view(row);});}
 public List<Capture> list(){permission("documents:read");return tx.execute(()->em.createQuery("select d from CapturedDocument d order by d.capturedAt desc,d.id",CapturedDocument.class).setMaxResults(100).getResultList().stream().filter(d->{try{sources.authorize(d.templateId);return true;}catch(AccessDeniedException denied){return false;}}).map(this::view).toList());}
 public String preview(UUID id,String paper){return DocumentHtml.render(get(id),paper,true);}
 private String originalTemplate(String kind){return switch(kind){case "INVOICE"->"DOC02";case "QUOTATION"->"DOC03";case "CREDIT_NOTE"->"DOC10";default->throw new IllegalStateException("Unknown original family");};}
 private Capture printable(UUID id,boolean capture){if(capture)return get(id);permission("documents:read");var d=originals.get(id);String template=originalTemplate(d.kind());sources.authorize(template);var m=sources.read(template,d.sourceId());return new Capture(d.id(),template,d.sourceId(),null,d.issuedAt(),d.sha256(),new Content("CAPTURE-ENFR-1",sources.template(template),m.originalIssuer(),m.body(),null,d.issuedAt()));}
 public PrintResult print(UUID id,boolean capture,PrintRequest r){permission("documents:print");if(r==null||r.operationId()==null)throw new IllegalArgumentException("Operation required");reason(r.reason());DocumentHtml.paper(r.paper());return tx.execute(()->{var document=printable(id,capture);return command(r.operationId(),"DOCUMENT_PRINT",List.of(id,capture,r),PrintResult.class,()->{
  var s=TenantContext.current();em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:key,0))").setParameter("key","document-print:"+s.tenantId()+":"+id).getSingleResult();long count=em.createQuery("select count(p) from DocumentPrintAttempt p where "+(capture?"p.captureId":"p.originalId")+"=:id",Long.class).setParameter("id",id).getSingleResult();var p=new DocumentPrintAttempt();p.tenantId=s.tenantId();p.companyId=s.companyId();p.branchId=s.branchId();p.id=UUID.randomUUID();p.operationId=r.operationId();p.actorId=s.actorId();p.originalId=capture?null:id;p.captureId=capture?id:null;p.paper=r.paper();p.duplicate=!capture||count>0;p.reason=r.reason();p.documentHash=document.sha256();p.requestedAt=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);em.persist(p);em.flush();event(r.operationId(),"DocumentPrintRequested",p.id);return result(p,"REQUESTED",DocumentHtml.render(document,p.paper,p.duplicate));
 });});}
 private PrintResult result(DocumentPrintAttempt p,String status,String html){return new PrintResult(p.id,p.captureId==null?p.originalId:p.captureId,p.captureId!=null,p.actorId,p.requestedAt,p.paper,p.duplicate,p.reason,p.documentHash,status,html);}
 public List<PrintResult> attempts(){permission("documents:read");return tx.execute(()->{
  var answer=new ArrayList<PrintResult>();for(var p:em.createQuery("select p from DocumentPrintAttempt p order by p.requestedAt desc,p.id",DocumentPrintAttempt.class).setMaxResults(100).getResultList()){try{printable(p.captureId==null?p.originalId:p.captureId,p.captureId!=null);}catch(AccessDeniedException denied){continue;}var outcomes=em.createQuery("select o from DocumentPrintOutcome o where o.attemptId=:id",DocumentPrintOutcome.class).setParameter("id",p.id).getResultList();answer.add(result(p,outcomes.isEmpty()?"REQUESTED":outcomes.getFirst().status,""));}return List.copyOf(answer);
 });}
 public Outcome outcome(UUID id,OutcomeRequest r){permission("documents:print");if(r==null||r.operationId()==null||r.status()==null||!Set.of("PRINTED","FAILED").contains(r.status()))throw new IllegalArgumentException("PRINTED or FAILED required; this is client-attested printer outcome");reason(r.reason());return tx.execute(()->{var s=TenantContext.current();/* Attempts are immutable; serialize outcomes without UPDATE privileges on the source fact. */em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:key,0))").setParameter("key","document-print-outcome:"+s.tenantId()+":"+s.companyId()+":"+id).getSingleResult();var p=em.find(DocumentPrintAttempt.class,new DocumentSnapshot.Key(s.tenantId(),s.companyId(),id));if(p==null)throw new NoSuchElementException("Print attempt not found");printable(p.captureId==null?p.originalId:p.captureId,p.captureId!=null);return command(r.operationId(),"DOCUMENT_PRINT_OUTCOME",List.of(id,r),Outcome.class,()->{
  if(!em.createQuery("select o from DocumentPrintOutcome o where o.attemptId=:id",DocumentPrintOutcome.class).setParameter("id",id).getResultList().isEmpty())throw new IllegalStateException("Outcome already recorded; retry printing as a new attempt");var o=new DocumentPrintOutcome();o.tenantId=s.tenantId();o.companyId=s.companyId();o.branchId=s.branchId();o.id=UUID.randomUUID();o.attemptId=id;o.operationId=r.operationId();o.actorId=s.actorId();o.status=r.status();o.reason=r.reason();o.recordedAt=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MICROS);em.persist(o);em.flush();event(r.operationId(),"DocumentPrintOutcomeRecorded",o.id);return new Outcome(o.id,id,o.actorId,o.recordedAt,o.status,o.reason);
 });});}
 private void reason(String r){if(r==null||r.trim().length()<3||r.length()>2000)throw new IllegalArgumentException("Reason must contain 3–2000 characters");}
 private <T>T command(UUID operation,String kind,Object request,Class<T> type,Supplier<T> work){String hash=DefaultDocumentService.sha(kind+"\n"+json.writeValueAsString(request));return tx.execute(()->{var s=TenantContext.current();em.createNativeQuery("select 1 from pg_advisory_xact_lock(hashtextextended(:key,0))").setParameter("key",s.tenantId()+":"+operation).getSingleResult();var found=em.createNativeQuery("select request_hash,response_json::text,company_id,branch_id,actor_id,source_type from idempotency_result where tenant_id=:t and operation_id=:o").setParameter("t",s.tenantId()).setParameter("o",operation).getResultList();if(!found.isEmpty()){Object[] old=(Object[])found.getFirst();if(!hash.equals(old[0])||!s.companyId().equals(old[2])||!s.branchId().equals(old[3])||!s.actorId().equals(old[4])||!kind.equals(old[5]))throw new IllegalStateException("Operation identity conflicts with request, actor or scope");if(old[1]==null)throw new IllegalStateException("Original receipt expired; reconcile before retry");return json.readValue((String)old[1],type);}T result=work.get();UUID source=result instanceof Capture c?c.id():result instanceof PrintResult p?p.id():((Outcome)result).id();em.createNativeQuery("insert into idempotency_result(tenant_id,operation_id,company_id,branch_id,request_hash,source_type,source_id,response_json) values(:t,:o,:c,:b,:h,:k,:s,cast(:r as jsonb))").setParameter("t",s.tenantId()).setParameter("o",operation).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("h",hash).setParameter("k",kind).setParameter("s",source).setParameter("r",json.writeValueAsString(result)).executeUpdate();return result;});}
 private void event(UUID operation,String type,UUID source){var s=TenantContext.current();em.createNativeQuery("insert into outbox_event(tenant_id,id,company_id,branch_id,operation_id,event_type,aggregate_type,aggregate_id,payload) values(:t,:id,:c,:b,:o,:type,'Document',:source,cast(:payload as jsonb))").setParameter("t",s.tenantId()).setParameter("id",UUID.randomUUID()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",operation).setParameter("type",type).setParameter("source",source).setParameter("payload",json.writeValueAsString(Map.of("actorId",s.actorId(),"documentEvent",type))).executeUpdate();}
}
